use std::hash::Hash;
use std::rc::Rc;
use std::cell::RefCell;

/// A doubly-linked list node. We use Rc<RefCell<>> to allow multiple references
/// and interior mutability for the prev/next pointers.
struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<Rc<RefCell<Node<K, V>>>>,
    next: Option<Rc<RefCell<Node<K, V>>>>,
}

/// LRU Cache with O(1) get and put operations.
/// Uses a HashMap for O(1) key lookup and a doubly-linked list for ordering.
struct LRUCache<K, V>
where
    K: Eq + Hash + Clone,
{
    capacity: usize,
    map: HashMap<K, Rc<RefCell<Node<K, V>>>>,
    head: Option<Rc<RefCell<Node<K, V>>>>,
    tail: Option<Rc<RefCell<Node<K, V>>>>,
}

